"""3D climbing environment on the real HKUST boulder wall.

Tasks are boulder problems generated by the synthetic routesetter over the
real hold annotations (positions, depths, pull directions, strengths). The
observation is a fixed set of "task hold slots" (chain sorted bottom-up plus
a couple of usable volumes), so action semantics stay stable within an
episode.

Action space (Discrete): 0 noop | 1..K grab slot | K+1..K+4 release limb | K+5 dyno.

The grip model makes the 3D angles matter: grabbing a hold only helps if the
force the body needs there fits inside the hold's pull cone (real annotation
direction + depth-informed tilt) and its strength limit.
"""

import gymnasium as gym
import numpy as np
from gymnasium import spaces

from physics.body3d import ClimberBody3D
from wallimport.importer import GymWall3D, Hold3D, import_boulder_wall
from wallimport.routeset import generate_route, task_from_route

MAX_SLOTS = 16

DEFAULT_3D_REWARD = {
    "progress": 1.0,
    "hold_bonus": 0.25,
    "time_penalty": -0.01,
    "reach_penalty": -0.3,
    "slip_penalty": -0.5,
    "fall_penalty": -1.0,
    "success_bonus": 10.0,
    "stability_bonus": 0.02,
    "target_touch": 0.3,
    "dyno_attempt": 0.0,
    "dyno_catch": 1.0,
}


class ClimbingEnv3D(gym.Env):
    """Route-climbing task on the imported 3D gym wall."""

    metadata = {"render_modes": ["human"], "render_fps": 10}

    def __init__(self, wall: GymWall3D = None, route_seed: int = 0,
                 difficulty: str = "medium", max_steps=250,
                 dt=0.1, physics_substeps=5, reward_config=None,
                 max_slots=MAX_SLOTS, task_holds=None):
        super().__init__()
        self.wall = wall if wall is not None else import_boulder_wall()
        self.route_seed = route_seed
        self.difficulty = difficulty
        self.max_steps = max_steps
        self.dt = dt
        self.physics_substeps = physics_substeps
        self.rc = dict(DEFAULT_3D_REWARD)
        if reward_config:
            self.rc.update(reward_config)
        self.max_slots = max_slots

        if task_holds is None:
            chain = generate_route(self.wall, seed=route_seed, difficulty=difficulty)
            task_holds = task_from_route(self.wall, chain, max_slots=max_slots)
        self.task_holds = task_holds
        self.n_slots = len(self.task_holds)
        self.target_hold = task_holds[-1]
        self.bounds = (self.wall.width, self.wall.height, 1.4)

        self.action_space = spaces.Discrete(1 + self.max_slots + 4 + 1)

        obs_size = 9 + 4 * 5 + self.max_slots * 13 + 4
        self.observation_space = spaces.Box(
            low=-np.inf, high=np.inf, shape=(obs_size,), dtype=np.float32
        )

        self.body = None
        self.step_count = 0
        self._prev_dist = None
        self._grabbed = set()
        self._target_hold_steps = 0
        self._was_dyno = False
        self._dyno_release_y = 0.0

    # ---- observation -------------------------------------------------------
    def _slot_features(self, idx, hold, grabbable_flags):
        limb = None
        for l in self.body.limbs:
            if l.attached and l.hold is not None and l.hold.id == hold.id:
                limb = l
        rel = hold.pos - self.body.com
        return np.array([
            rel[0], rel[1], rel[2],
            hold.depth,
            hold.pull_axis[0], hold.pull_axis[1], hold.pull_axis[2],
            hold.cone_cos,
            min(hold.f_max_hand / 1000.0, 1.5),
            min(hold.f_max_foot / 1500.0, 1.5),
            1.0 if hold is self.target_hold else 0.0,
            1.0 if limb is not None else 0.0,
            grabbable_flags[idx],
        ], dtype=np.float32)

    def _get_obs(self):
        b = self.body
        parts = [b.com, b.vel, b.torso_up()]
        _, _, _, joints = b.joints_all()
        for i, limb in enumerate(b.limbs):
            if limb.attached and limb.contact is not None:
                rel = limb.contact - b.com
                parts.append(np.array([rel[0], rel[1], rel[2], 1.0, limb.grip_util]))
            else:
                u = b.torso_up()
                length = b.a.arm_reach if i in (0, 1) else b.a.leg_reach
                end = joints[i] - u * length * 0.85
                rel = end - b.com
                parts.append(np.array([rel[0], rel[1], rel[2], 0.0, 0.0]))

        grabbable = self._grabbable_flags(joints)
        for idx, hold in enumerate(self.task_holds):
            parts.append(self._slot_features(idx, hold, grabbable))
        for _ in range(self.n_slots, self.max_slots):
            parts.append(np.zeros(13, dtype=np.float32))

        target_rel = self.target_hold.pos - b.com
        dist = np.linalg.norm(target_rel)
        parts.append(np.array([target_rel[0], target_rel[1], target_rel[2], dist]))
        return np.concatenate(parts).astype(np.float32)

    def _grabbable_flags(self, joints=None):
        """Per-hold grab-ability, visible to the policy BEFORE committing.

        1.0 = a free limb can grab it now; 0.5 = in reach of a limb that is
        currently attached (grab requires releasing it first); 0.0 = out of
        reach. Without the 0.5 level the agent would see zero options while
        hanging with all four limbs attached and never learn to move.
        """
        if joints is None:
            _, _, _, joints = self.body.joints_all()
        flags = np.zeros(len(self.task_holds))
        reach_f = 1.3 if self.body.in_dyno else 1.02
        for idx, hold in enumerate(self.task_holds):
            want_hand = hold.pos[1] > self.body.com[1] - 0.05
            role = (0, 1) if want_hand else (2, 3)
            # nearest joint of that role, regardless of attachment
            limb_idx = min(role, key=lambda i: np.linalg.norm(hold.pos - joints[i]))
            length = self.body.a.arm_reach if limb_idx in (0, 1) else self.body.a.leg_reach
            if np.linalg.norm(hold.pos - joints[limb_idx]) <= length * reach_f:
                flags[idx] = 0.5 if self.body.limbs[limb_idx].attached else 1.0
        return flags

    # ---- episode -----------------------------------------------------------
    def _pick_start_holds(self):
        """Feet + hand holds for a compact, stable start stance.

        The four lowest chain holds can be spread wide after lateral drift,
        so we cluster the start around the lowest hold and try a few stance
        combinations until the grip check is satisfied.
        """
        cand = self.task_holds[:8]
        h0 = cand[0]
        near = sorted(cand[1:], key=lambda h: np.linalg.norm(h.pos - h0.pos))[:5]
        pool = sorted([h0] + near, key=lambda h: h.pos[1])
        stances = []
        for shift in range(0, max(1, len(pool) - 3)):
            feet, hands = pool[shift:shift + 2], pool[shift + 2:shift + 4]
            if len(feet) == 2 and len(hands) == 2:
                stances.append((feet, hands))
        if not stances:
            feet = pool[:2] if len(pool) >= 2 else [pool[0]] * 2
            hands = pool[2:4] if len(pool) >= 4 else feet
            stances.append((feet, hands))
        return stances

    def _attach_start(self, feet, hands):
        hand_anchor = np.mean([h.pos for h in hands], axis=0)
        start_com = np.array([
            hand_anchor[0],
            max(0.62, hand_anchor[1] - 0.30),
            min(0.75, hand_anchor[2] + 0.30),
        ])
        self.body = ClimberBody3D(start_com)
        for limb_idx, hold in [(0, hands[0]), (1, hands[1]),
                               (2, feet[0]), (3, feet[1])]:
            limb = self.body.limbs[limb_idx]
            limb.attached = True
            limb.hold = hold
            limb.contact = np.asarray(hold.pos, dtype=np.float64).copy()
            limb.grip_util = 0.0
        self.body._update_wall_normal()

    def reset(self, seed=None, options=None):
        super().reset(seed=seed)
        self.step_count = 0
        self._target_hold_steps = 0
        self._was_dyno = False
        self._dyno_release_y = 0.0
        best = None
        for feet, hands in self._pick_start_holds():
            self._attach_start(feet, hands)
            # quasi-settle, then verify the stance is grip-feasible
            for _ in range(10):
                self.body.step(0.02, bounds=self.bounds)
            rep = self.body.check_grips()
            if best is None:
                best = (feet, hands)
            if rep.feasible:
                best = (feet, hands)
                break
        feet, hands = best
        start_holds = list(hands) + list(feet)
        if any(self.body.limbs[i].hold is not start_holds[i] for i in range(4)):
            self._attach_start(feet, hands)
        self._grabbed = {h.id for h in hands + feet}
        self._prev_dist = np.linalg.norm(self.body.com - self.target_hold.pos)
        return self._get_obs(), {}

    # ---- step --------------------------------------------------------------
    def step(self, action):
        self.step_count += 1
        comp = {}
        grabbed_new = failed_reach = False
        dyno_attempted = dyno_caught = False

        K = self.max_slots
        was_dyno = self.body.in_dyno
        if 1 <= action <= K and action <= self.n_slots:
            hold = self.task_holds[action - 1]
            reach_f = 1.3 if was_dyno else 1.02
            ok, limb_idx = self.body.try_grab(hold, max_reach_factor=reach_f)
            if ok:
                grabbed_new = hold.id not in self._grabbed
                self._grabbed.add(hold.id)
                # a "catch" only counts if the dyno actually gained height —
                # otherwise release-and-regrab loops would farm the bonus
                if was_dyno and hold.pos[1] > self._dyno_release_y + 0.25:
                    dyno_caught = True
            elif limb_idx >= 0:
                failed_reach = True
        elif K + 1 <= action <= K + 4:
            self.body.release(action - K - 1)
        elif action == K + 5:
            self._dyno_release_y = self.body.com[1]
            self.body.dyno(self.target_hold.pos)
            dyno_attempted = True

        self._was_dyno = self.body.in_dyno
        sub = self.dt / self.physics_substeps
        for _ in range(self.physics_substeps):
            self.body.step(sub, bounds=self.bounds)
        report = self.body.check_grips()
        slipped = bool(self.body.slip_events)

        target_rel = self.target_hold.pos - self.body.com
        dist = np.linalg.norm(target_rel)
        height = self.body.com[1]

        comp["progress"] = self.rc["progress"] * (self._prev_dist - dist)
        comp["time_penalty"] = self.rc["time_penalty"]
        if grabbed_new:
            comp["hold_bonus"] = self.rc["hold_bonus"]
        if failed_reach:
            comp["reach_penalty"] = self.rc["reach_penalty"]
        if slipped:
            comp["slip_penalty"] = self.rc["slip_penalty"]
        if dyno_attempted:
            comp["dyno_bonus"] = self.rc["dyno_attempt"]
        if dyno_caught:
            comp["dyno_bonus"] = comp.get("dyno_bonus", 0.0) + self.rc["dyno_catch"]
        if self.body.num_attached() > 0:
            comp["stability_bonus"] = self.rc["stability_bonus"] * float(
                np.clip(report.min_margin, 0.0, 1.0))

        # success: a hand parked on the target hold for two consecutive steps
        hand_on_target = any(
            self.body.limbs[i].attached
            and self.body.limbs[i].hold is self.target_hold
            for i in (0, 1)
        )
        if hand_on_target and self.body.num_attached() >= 2:
            self._target_hold_steps += 1
            comp["target_touch"] = self.rc["target_touch"]
        else:
            self._target_hold_steps = 0
        self._prev_dist = dist

        terminated = truncated = False
        if self._target_hold_steps >= 2:
            comp["success_bonus"] = self.rc["success_bonus"]
            terminated = True
        elif self.body.com[1] < 0.3:
            comp["fall_penalty"] = self.rc["fall_penalty"]
            terminated = True
        if self.step_count >= self.max_steps:
            truncated = True

        reward = float(sum(comp.values()))
        info = {
            "comp": comp,
            "height": height,
            "dist": dist,
            "attached": self.body.num_attached(),
            "task": f"synth-{self.difficulty}-{self.route_seed}",
            "slipped": slipped,
            "dyno": self.body.in_dyno,
            "target_reached": terminated and self._target_hold_steps >= 2,
        }
        return self._get_obs(), reward, terminated, truncated, info

    def render(self):
        pass
